import { Bank } from "./dsl";

/** Labour Codes (in force from 21 Nov 2025): overview, Code on Wages, IR Code, OSH Code. */
const b = new Bank("labour1");

b.t("Labour Codes – Overview");
b.q(1, "How many central labour laws were consolidated into the four Labour Codes that came into force on 21 November 2025?", ["29", "44", "13", "21"], "The four Codes amalgamate 29 central labour laws: 4 in the Code on Wages, 3 in the Industrial Relations Code, 9 in the Code on Social Security and 13 in the OSH Code.");
b.q(1, "Which of the four Labour Codes was the first to receive Presidential assent?", ["Code on Wages", "Industrial Relations Code", "Code on Social Security", "Occupational Safety, Health and Working Conditions Code"], "The Code on Wages received assent in August 2019; the other three Codes were passed in September 2020.");
b.q(2, "The recommendation to group India's labour laws into a few functional codes is most closely associated with which body?", ["Second National Commission on Labour (Ravindra Varma)", "Royal Commission on Labour (Whitley)", "First National Commission on Labour (Gajendragadkar)", "Sarkaria Commission"], "The Second NCL (report 2002), chaired by Ravindra Varma, recommended rationalising central laws into broad codes such as wages, industrial relations, social security and safety.");
b.q(1, "On which date did all four Labour Codes become effective across India?", ["21 November 2025", "1 April 2025", "15 August 2024", "26 January 2026"], "The Government notified 21 November 2025 as the effective date of the Code on Wages, the IR Code, the Code on Social Security and the OSH Code, with some provisions operationalised in phases through rules.");
b.st(2, "Consider the following pairs of Labour Code and the number of laws it subsumes:", ["Code on Wages, 2019 — 4 laws", "Industrial Relations Code, 2020 — 3 laws", "Code on Social Security, 2020 — 13 laws"], [1, 2], "Code on Wages subsumes 4 laws and the IR Code 3. The Code on Social Security subsumes 9 laws; it is the OSH Code that subsumes 13.", "Which of the pairs given above is/are correctly matched?");
b.mt(2, "Match the Labour Code with a law it subsumed:", [["Code on Wages", "Payment of Bonus Act, 1965"], ["Industrial Relations Code", "Trade Unions Act, 1926"], ["Code on Social Security", "Employees' Compensation Act, 1923"], ["OSH Code", "Mines Act, 1952"]], "Bonus → Code on Wages; Trade Unions → IR Code; Employees' Compensation → Code on Social Security; Mines → OSH Code.", "Labour Code", "Subsumed law");
b.q(2, "Labour as a subject of legislation in India falls primarily under which part of the Seventh Schedule?", ["Concurrent List", "Union List", "State List", "Residuary powers only"], "Trade unions, industrial disputes, social security and welfare of labour are Entries 22–24 of the Concurrent List, which is why both the Centre and States frame rules under the Codes.");
b.hm(2, "Consider the following statements about the Labour Codes:", ["Every employer must issue an appointment letter to each employee.", "Gig and platform workers are defined in a central labour law for the first time.", "Fixed-term employment is recognised with benefits on par with permanent workers."], 3, "All three are features of the Codes: appointment letters are mandatory under the OSH Code, gig/platform workers are defined in the Code on Social Security, and the IR Code recognises fixed-term employment with parity of benefits.");
b.q(3, "Under the Labour Codes, the designation 'Inspector-cum-Facilitator' signals a shift towards:", ["Advising employers on compliance besides inspecting, with randomised web-based inspection schemes", "Abolition of all labour inspections", "Inspections only on written complaint by a trade union", "Transfer of inspection powers to industry associations"], "The Codes rename inspectors as Inspector-cum-Facilitators who also guide compliance; inspection schemes may be web-based and randomised to reduce discretion.");
b.q(3, "Which feature of the Labour Codes is aimed at reducing the compliance burden on employers through single-window processes?", ["Single registration, single licence and single return for establishments", "Abolition of minimum wages", "Exemption of all MSMEs from every labour law", "Replacing labour courts with civil courts"], "The Codes provide for one registration, one licence and one return instead of separate filings under multiple Acts.");
b.q(2, "Under the Labour Codes, offences punishable only with fine may generally be:", ["Compounded, typically by paying a prescribed share of the maximum fine", "Tried only by a Sessions Court", "Punished with mandatory imprisonment", "Ignored if the employer is an MSME"], "The Codes introduce compounding of fine-only offences (commonly at 50% of the maximum fine) to decriminalise minor violations.");
b.ar(2, "The Labour Codes extend minimum wage protection to workers in the unorganised sector as well.", "The Minimum Wages Act, 1948 applied only to scheduled employments.", "a", "Under the 1948 Act, minimum wages applied only to employments listed in the schedule; the Code on Wages universalises minimum wages to all employees, which explains the extension.");
b.q(1, "Which Code introduced the concept of a 'national floor wage'?", ["Code on Wages, 2019", "Industrial Relations Code, 2020", "Code on Social Security, 2020", "OSH Code, 2020"], "Section 9 of the Code on Wages empowers the Central Government to fix a floor wage below which no State may set its minimum wage.");
b.q(3, "Which of the following laws was NOT subsumed in any of the four Labour Codes?", ["Sexual Harassment of Women at Workplace (POSH) Act, 2013", "Plantations Labour Act, 1951", "Equal Remuneration Act, 1976", "Cine-Workers Welfare Fund Act, 1981"], "The POSH Act remains a separate law. Plantations Labour went into the OSH Code, Equal Remuneration into the Code on Wages, and Cine-Workers Welfare Fund into the Code on Social Security.");
b.q(3, "Which of these laws continues to operate outside the four Labour Codes?", ["Child and Adolescent Labour (Prohibition and Regulation) Act, 1986", "Industrial Employment (Standing Orders) Act, 1946", "Motor Transport Workers Act, 1961", "Payment of Wages Act, 1936"], "The child labour law was not codified. Standing Orders went into the IR Code, Motor Transport Workers into the OSH Code and Payment of Wages into the Code on Wages.");
b.q(2, "Who chaired the Second National Commission on Labour that submitted its report in 2002?", ["Ravindra Varma", "P. B. Gajendragadkar", "J. H. Whitley", "V. V. Giri"], "Ravindra Varma chaired the Second NCL (1999–2002). Gajendragadkar chaired the First NCL (1966–69).");

b.t("Code on Wages");
b.mt(1, "Match the law with the Code into which it was merged:", [["Minimum Wages Act, 1948", "Code on Wages"], ["Industrial Disputes Act, 1947", "Industrial Relations Code"], ["Maternity Benefit Act, 1961", "Code on Social Security"], ["Factories Act, 1948", "OSH Code"]], "Minimum Wages → Code on Wages; ID Act → IR Code; Maternity Benefit → Code on Social Security; Factories → OSH Code.", "Old law", "Code");
b.q(1, "The Code on Wages, 2019 subsumes all of the following EXCEPT:", ["Payment of Gratuity Act, 1972", "Payment of Wages Act, 1936", "Payment of Bonus Act, 1965", "Equal Remuneration Act, 1976"], "The Code on Wages subsumes Payment of Wages, Minimum Wages, Payment of Bonus and Equal Remuneration. Gratuity is in the Code on Social Security.");
b.q(2, "Under the Code on Wages, monthly wages must be paid before the expiry of which day of the succeeding month?", ["7th day", "10th day", "15th day", "Last working day"], "Section 17: for monthly wage periods, wages are payable before the expiry of the seventh day of the succeeding month.");
b.q(2, "A worker engaged on a weekly wage period must be paid under the Code on Wages:", ["On the last working day of the week, before the weekly holiday", "Within 7 days after the week ends", "Every fortnight", "On the first working day of the next week"], "Weekly wages are due on the last working day of the week, i.e., before the weekly holiday.");
b.q(2, "For a fortnightly wage period, the Code on Wages requires payment:", ["Before the end of the second day after the end of the fortnight", "Within seven days of the fortnight", "On the 15th and last day of the month regardless of the wage period", "Within 48 hours of a written demand"], "Fortnightly wages must be paid before the end of the second day after the fortnight closes.");
b.q(1, "A daily-rated casual worker must be paid under the Code on Wages:", ["At the end of the shift", "At the end of the week", "At the end of the month", "Within three days"], "For daily wage periods, wages are payable at the end of the shift.");
b.q(2, "When an employee is removed, dismissed, retrenched or resigns, the Code on Wages requires the wages due to be paid within:", ["Two working days", "Seven days", "Thirty days", "The next wage period"], "Section 17(2): wages of an employee who is removed, dismissed, retrenched, resigns or becomes unemployed due to closure must be paid within two working days.");
b.q(2, "Under the Code on Wages, the total deductions from an employee's wages in a wage period cannot exceed what share of the wages?", ["50%", "25%", "75%", "33%"], "Section 18 caps total authorised deductions at fifty per cent of the wages.");
b.q(3, "Under the Code on Wages, if excluded components such as HRA, conveyance and overtime exceed a certain share of total remuneration, the excess is added back to 'wages'. That share is:", ["50%", "40%", "60%", "25%"], "The proviso to Section 2(y) deems the amount by which excluded payments exceed one-half (50%) of total remuneration to be wages — this prevents a deflated 'basic' for computing PF, gratuity etc.");
b.q(2, "Overtime work under the Code on Wages must be paid at a rate of at least:", ["Twice the normal rate of wages", "One and a half times the normal rate", "The normal rate plus 25%", "The minimum wage only"], "Section 14 mandates overtime at not less than twice the normal rate of wages.");
b.q(2, "The Code on Wages requires minimum wage rates to be reviewed or revised by the appropriate government ordinarily at an interval not exceeding:", ["Five years", "Three years", "Ten years", "One year"], "Section 8(4): minimum rates are to be reviewed/revised ordinarily at intervals not exceeding five years.");
b.st(2, "Consider the following statements regarding minimum wages under the Code on Wages:", ["The Central Government fixes a floor wage which may differ for different geographical areas.", "A State may fix a minimum wage lower than the floor wage if its cost of living is low."], [1], "The floor wage may vary by geographical area, but no State can fix a minimum wage below the floor wage; if existing rates are higher they cannot be reduced.");
b.q(2, "Which factors does the Code on Wages specify for fixing minimum wages?", ["Skill category and arduousness of work, besides geographical area", "Only the employer's paying capacity", "Only the age and gender of the worker", "The size of the employer's share capital"], "Minimum wages are fixed taking into account skill (unskilled, semi-skilled, skilled, highly skilled), arduousness, geographical area and other factors — never gender.");
b.q(1, "Equal remuneration provisions under the Code on Wages prohibit discrimination on the ground of gender. Here 'gender' expressly includes:", ["Transgender persons", "Only women", "Only men and women", "Persons with disabilities"], "Section 3 bars discrimination on the ground of gender, including transgender identity, in wages and in recruitment for the same or similar work.");
b.q(2, "Under the Code on Wages, the minimum bonus payable in an accounting year is:", ["8.33% of wages or ₹100, whichever is higher", "10% of wages", "8.33% of wages or ₹1,000, whichever is higher", "One month's wages"], "Section 26: minimum bonus is 8.33% of wages earned or ₹100, whichever is higher, whether or not the employer has allocable surplus.");
b.q(1, "The maximum bonus payable under the Code on Wages is:", ["20% of wages", "8.33% of wages", "25% of wages", "There is no ceiling"], "Where allocable surplus exceeds the minimum bonus, bonus can go up to a maximum of 20% of wages.");
b.q(2, "To be eligible for statutory bonus, an employee must have worked in the establishment for at least how many days in the accounting year?", ["30 days", "60 days", "90 days", "240 days"], "Section 26(1): an employee who has worked not less than thirty days in the accounting year is eligible.");
b.q(3, "Which ground for disqualification from bonus was newly added in the Code on Wages (it was not in the Payment of Bonus Act, 1965)?", ["Sexual harassment", "Fraud", "Theft or misappropriation", "Riotous or violent behaviour on the premises"], "The Code adds conviction for sexual harassment as a ground for disqualification alongside fraud, violent behaviour, theft, misappropriation and sabotage.");
b.q(2, "Bonus under the Code on Wages must ordinarily be paid within what period from the close of the accounting year?", ["Eight months", "One month", "Six months", "One year"], "Bonus is payable within eight months from the close of the accounting year (unless the period is extended).");
b.q(3, "Under the bonus provisions, an excess or deficit of allocable surplus can be carried forward ('set on' / 'set off') up to which accounting year?", ["The fourth accounting year", "The second accounting year", "The tenth accounting year", "It cannot be carried forward"], "The scheme of set-on and set-off allows the surplus or shortfall to be carried forward and utilised up to and inclusive of the fourth following accounting year.");
b.q(2, "What is the time limit for filing a claim for unpaid wages, bonus or less-than-minimum wages before the authority under the Code on Wages?", ["Three years", "Six months", "One year", "Ten years"], "Section 45 allows claims to be filed within three years from the date the claim arises.");
b.q(2, "The Central Advisory Board under the Code on Wages is tripartite. What share of its members must be women?", ["One-third", "One-half", "One-fourth", "There is no requirement"], "The Board includes employers, employees and independent persons; one-third of its members are to be women.");
b.q(3, "Under the Code on Wages, the bonus provisions apply to an establishment that employs on any day during an accounting year at least:", ["20 persons", "10 persons", "50 persons", "100 persons"], "The bonus chapter applies to every establishment in which twenty or more persons are employed on any day during an accounting year (besides factories).");
b.q(3, "Under the Code on Wages, the Central Government is the 'appropriate government' for all of the following EXCEPT:", ["A private textile mill in Coimbatore", "Railways", "Mines", "Major ports"], "The Centre is the appropriate government for railways, mines, oil fields, major ports, air transport, banking, insurance and Central PSUs; a private textile mill is under the State Government.");
b.st(3, "Consider the following statements about 'wages' as defined in the Code on Wages:", ["House rent allowance is excluded from wages.", "Dearness allowance is included in wages.", "Statutory bonus forms part of wages."], [1, 2], "Wages include basic pay, DA and retaining allowance. HRA, statutory bonus, overtime, commission, conveyance and gratuity are excluded (subject to the 50% rule).");
b.q(1, "Under the Code on Wages, who is responsible for paying wages to employees in an establishment?", ["The employer", "The appropriate government", "The trade union", "The Inspector-cum-Facilitator"], "The employer is primarily responsible for timely payment of wages; where a contractor fails, the principal employer may be made liable to pay.");
b.q(3, "If a contractor fails to pay the minimum wages due to contract workers, the Code on Wages makes whom liable to pay the unpaid amount?", ["The principal employer (or the company/establishment)", "The Inspector-cum-Facilitator", "The contract workers' trade union", "The State Labour Department"], "Section 17(5) obliges the company/firm/establishment (principal employer) to pay if the contractor fails, with the right to recover from the contractor.");
b.q(2, "The penalty for paying an employee less than the amount due under the Code on Wages, for a first offence, is a fine of up to:", ["₹50,000", "₹5,000", "₹10 lakh", "₹500"], "Section 54(1)(a) prescribes a fine up to ₹50,000; repeat offences within five years attract imprisonment up to three months or a fine up to ₹1 lakh or both.");
b.q(2, "Under the Code on Wages, minimum wages are normally fixed by reference to all of the following time units EXCEPT:", ["Per piece-rate of shareholders' dividend", "By the hour", "By the day", "By the month"], "Minimum wages may be fixed by time (hour, day, month) or by piece. A dividend-based rate is not a wage concept.");
b.ar(3, "Under the Code on Wages, the normal working day of an adult worker must ordinarily be fixed so that it does not exceed a prescribed number of hours.", "Long working hours undermine the purpose of fixing a minimum time-rated wage.", "a", "The appropriate government fixes the number of hours constituting a normal working day (rules prescribe a maximum, commonly 8 hours on a 48-hour week). This protects the value of a time-rated minimum wage.");
b.q(1, "Which body determines the national floor wage under the Code on Wages?", ["The Central Government", "The Reserve Bank of India", "The Finance Commission", "The Supreme Court"], "The Central Government fixes the floor wage after considering the minimum living standards of workers and advice from the Central Advisory Board.");
b.q(2, "Under the Code on Wages, the employer may make deductions from wages for all the following EXCEPT:", ["Penalties imposed by the employer without any notified act or omission", "Fines for acts and omissions specified with prior approval", "Recovery of advances", "Income tax payable by the employee"], "Fines are allowed only for acts/omissions notified with prior approval; arbitrary penalties are not authorised deductions.");
b.q(3, "Under the Code on Wages, a fine imposed on an employee for an act or omission cannot exceed what proportion of the wages payable for that wage period?", ["3%", "10%", "25%", "50%"], "Section 19 caps a fine at three per cent of wages payable in respect of the wage period, and it must be recovered within 90 days.");
b.q(2, "The Code on Wages provisions on timely payment and authorised deductions apply to:", ["All employees, irrespective of their wage level", "Only employees earning up to ₹24,000 a month", "Only factory workers", "Only government employees"], "Unlike the Payment of Wages Act (which applied only up to a wage ceiling), the Code's payment provisions cover all employees.");
b.q(3, "Under the Code on Wages, the 'accounting year' for bonus purposes ordinarily means:", ["The year commencing on 1 April, unless the establishment's books close on another date", "The calendar year only", "The year ending on the date of the last wage revision", "Any 12 months chosen by the union"], "Accounting year generally means the year beginning 1 April; for companies, the period for which accounts are prepared.");
b.q(1, "The salary ceiling for eligibility to bonus has historically been revised; under the 2015 amendment to the bonus law it was raised to:", ["₹21,000 per month", "₹10,000 per month", "₹15,000 per month", "₹25,000 per month"], "The Payment of Bonus (Amendment) Act, 2015 raised the eligibility ceiling from ₹10,000 to ₹21,000 per month and the calculation ceiling from ₹3,500 to ₹7,000 (or the minimum wage).");
b.q(3, "Under the Code on Wages, what is the purpose of a 'facilitator' notice before prosecution for a first-time contravention?", ["To give the employer an opportunity to comply within a set time before prosecution", "To authorise immediate arrest of the employer", "To impose a lifetime ban on the business", "To require union approval for any action"], "Inspector-cum-Facilitators must give an opportunity to comply within a specified period before launching prosecution for a first contravention, unless it is a repeat.");
b.q(2, "Under the Code on Wages, which authority hears claims arising out of non-payment or less payment of wages?", ["An officer not below the rank of Gazetted Officer appointed by the appropriate government", "Only the High Court", "The Central Board of Trustees, EPF", "The Lok Adalat exclusively"], "Section 45 empowers the appropriate government to appoint Gazetted Officers as authorities to hear and decide claims.");
b.st(1, "Consider the following statements about the Code on Wages:", ["It applies to both organised and unorganised sectors.", "It permits gender-based differences in wages for work of a similar nature."], [1], "The Code universalises minimum wage and timely payment provisions; it prohibits gender discrimination for same or similar work.");
b.q(2, "In the Code on Wages, the four skill categories used for fixing minimum wages are unskilled, semi-skilled, skilled and:", ["Highly skilled", "Supervisory", "Managerial", "Professional"], "The Code recognises four categories: unskilled, semi-skilled, skilled and highly skilled.");
b.q(3, "Under the bonus chapter of the Code on Wages, 'allocable surplus' for a company (other than a banking company) generally means what percentage of the available surplus?", ["67%", "60%", "50%", "80%"], "Allocable surplus is 67% of the available surplus for a company other than a banking company, and 60% in other cases.");
b.q(3, "Under the bonus provisions, a newly set up establishment is generally liable to pay bonus from the accounting year in which:", ["It derives profit, or the sixth accounting year after sale of goods begins, whichever is earlier", "It is registered", "It hires its 100th employee", "Its turnover crosses ₹1 crore"], "New establishments are exempt for the first five accounting years after commencing sale of goods/services, unless they make profit earlier.");

b.t("Industrial Relations Code");
b.q(1, "The Industrial Relations Code, 2020 subsumes which three laws?", ["Trade Unions Act 1926, Industrial Employment (Standing Orders) Act 1946 and Industrial Disputes Act 1947", "Factories Act 1948, Mines Act 1952 and Plantations Labour Act 1951", "Payment of Wages Act 1936, Minimum Wages Act 1948 and Payment of Bonus Act 1965", "ESI Act 1948, EPF Act 1952 and Gratuity Act 1972"], "The IR Code merges the Trade Unions, Standing Orders and Industrial Disputes Acts.");
b.q(2, "Under the IR Code, a trade union can be registered if it has as members at least:", ["10% of the workers or 100 workers, whichever is less, subject to a minimum of 7", "51% of the workers", "7 workers irrespective of the size of the establishment", "20% of the workers or 300 workers, whichever is more"], "Section 6 of the IR Code: no union is registered unless at least 10% of workers or 100 workers (whichever is less) are members, with at least seven members on the date of application.");
b.q(2, "Under the IR Code, a trade union having what minimum membership among workers on the muster roll is recognised as the sole negotiating union?", ["51% or more", "30% or more", "20% or more", "10% or more"], "Section 14: a union with 51% or more of the workers as members is recognised as the sole negotiating union.");
b.q(3, "If no trade union in an establishment has 51% membership, the IR Code provides for a negotiating council comprising unions that have at least what membership?", ["20% of the workers", "10% of the workers", "30% of the workers", "5% of the workers"], "A negotiating council is formed with representatives of unions having not less than 20% of the workers as members.");
b.q(2, "Under the IR Code, the provisions on standing orders apply to industrial establishments with how many workers?", ["300 or more", "100 or more", "50 or more", "20 or more"], "The threshold was raised from 100 (under the 1946 Act) to 300 workers.");
b.q(2, "Prior permission of the appropriate government for lay-off, retrenchment and closure is required under the IR Code in industrial establishments employing at least:", ["300 workers", "100 workers", "50 workers", "1,000 workers"], "Chapter X applies to establishments (factories, mines, plantations) with 300 or more workers; the government may raise this threshold by notification.");
b.q(2, "The 'Worker Re-skilling Fund' under the IR Code is financed by the employer contributing, for each retrenched worker, an amount equal to:", ["15 days' wages last drawn", "30 days' wages last drawn", "One month's basic pay", "3% of annual turnover"], "Section 83: the employer contributes 15 days' last drawn wages per retrenched worker; the amount is credited to the worker within 45 days of retrenchment.");
b.q(3, "Within how many days of retrenchment must the amount from the Worker Re-skilling Fund be credited to the retrenched worker's account?", ["45 days", "15 days", "90 days", "7 days"], "The amount (15 days' wages) is to be transferred to the worker's account within 45 days of retrenchment, to be used for upskilling.");
b.q(2, "Under the IR Code, no person employed in an industrial establishment shall go on strike without giving notice within how many days before striking?", ["60 days", "14 days", "30 days", "6 weeks"], "Section 62: strike notice must be given within sixty days before striking, and the strike cannot take place within fourteen days of giving notice.");
b.q(2, "Under the IR Code, a strike cannot be started within how many days of giving the strike notice?", ["14 days", "7 days", "21 days", "45 days"], "A strike is prohibited before the expiry of fourteen days from the date of notice.");
b.q(3, "A significant change in the IR Code regarding strike notice is that it now applies to:", ["All industrial establishments, not just public utility services", "Only public utility services", "Only government departments", "Only establishments with 1,000 workers"], "Under the ID Act notice was mandatory only in public utility services; the IR Code extends the notice requirement to all industrial establishments.");
b.q(3, "The IR Code's definition of 'strike' includes concerted casual leave taken on a given day by what proportion of the workers?", ["Fifty per cent or more", "Twenty-five per cent or more", "Ten per cent or more", "All workers"], "Section 2(zl) includes concerted casual leave on a given day by 50% or more workers in the definition of strike.");
b.q(2, "Under the IR Code, every industrial establishment employing how many or more workers must have a Grievance Redressal Committee?", ["20", "10", "50", "100"], "Section 4: establishments with twenty or more workers must have one or more Grievance Redressal Committees.");
b.q(3, "The maximum number of members in a Grievance Redressal Committee under the IR Code is:", ["10", "6", "12", "15"], "The committee has equal employer and worker representatives, total not exceeding ten, with chairpersonship alternating annually.");
b.q(2, "Under the IR Code, a Works Committee may be required in an industrial establishment with:", ["100 or more workers", "20 or more workers", "300 or more workers", "50 or more workers"], "Section 3 retains Works Committees for establishments employing 100 or more workers, to promote amity and good relations.");
b.q(2, "Under the IR Code, an Industrial Tribunal consists of:", ["A Judicial Member and an Administrative Member", "Only a retired High Court judge", "Three members nominated by trade unions", "The Chief Labour Commissioner alone"], "The IR Code reconstitutes Tribunals with two members — a Judicial Member and an Administrative Member — replacing Labour Courts.");
b.q(2, "Retrenchment compensation under the IR Code is equivalent to how many days' average pay for every completed year of continuous service?", ["15 days", "30 days", "7 days", "26 days"], "Retrenchment compensation is 15 days' average pay for every completed year of service or part exceeding six months.");
b.q(3, "Lay-off compensation under the IR Code is payable at what rate of basic wages plus dearness allowance?", ["50%", "100%", "75%", "25%"], "A laid-off worker gets compensation equal to 50% of basic wages and DA for the days of lay-off (other than weekly holidays).");
b.q(3, "Under the IR Code, an employer in a non-Chapter X establishment with 50 or more workers who intends to close down must give notice to the government at least how many days before closure?", ["60 days", "30 days", "90 days", "14 days"], "Section 74 requires at least sixty days' notice of intended closure in establishments with fifty or more workers.");
b.q(2, "The IR Code excludes from the definition of 'worker' a person employed in a supervisory capacity drawing wages exceeding (or as notified):", ["₹18,000 per month", "₹10,000 per month", "₹21,000 per month", "₹50,000 per month"], "Supervisory employees earning above ₹18,000 a month (or such higher amount as notified) are not 'workers'.");
b.st(3, "Consider the following regarding the definition of 'industry' in the IR Code:", ["Domestic service is excluded.", "Activities of government departments relating to defence research, atomic energy and space are excluded.", "Hospitals run on a commercial basis are excluded."], [1, 2], "The IR Code excludes domestic service, sovereign functions, charitable institutions and defence/atomic energy/space activities of government. Commercially run hospitals remain an 'industry'.");
b.q(2, "Which kind of employment did the IR Code formally recognise across all sectors, giving such workers the same wages and benefits as permanent workers?", ["Fixed-term employment", "Bonded employment", "Apprenticeship without stipend", "Honorary employment"], "Fixed-term employment is recognised; such workers get the same hours, wages, allowances and benefits as permanent workers doing similar work.");
b.q(1, "Under the IR Code, 'lock-out' means:", ["Temporary closing of a place of employment or suspension of work by the employer", "Refusal of workers to enter the premises", "Termination of a worker for misconduct", "Shifting of a factory to another State"], "Lock-out is the employer's counterpart of a strike — temporary closure or suspension of work or refusal to continue to employ workers.");
b.q(2, "The IR Code permits an individual worker to approach the Industrial Tribunal directly in disputes relating to discharge, dismissal or retrenchment:", ["After 45 days of applying to the conciliation officer", "Only after the trade union espouses the cause", "Only through the High Court", "Only after the appropriate government refers the dispute"], "Section 53 allows an individual worker to apply directly to the Tribunal after forty-five days from the application for conciliation.");
b.q(3, "Under the IR Code, during the pendency of conciliation proceedings before a conciliation officer, and for how many days after their conclusion, strikes are prohibited?", ["7 days", "14 days", "30 days", "60 days"], "Strikes and lock-outs are barred during conciliation and seven days after its conclusion; during Tribunal/arbitration proceedings and sixty days after.");
b.q(2, "Under the IR Code, disputes between trade unions (inter- or intra-union) are adjudicated by:", ["The Industrial Tribunal", "The Registrar of Trade Unions only", "The civil court", "The Election Commission"], "The IR Code empowers Industrial Tribunals to adjudicate disputes among trade unions, besides the Registrar's role in registration.");
b.q(3, "Under the IR Code, which authority recognises a trade union as a 'Central Trade Union' or 'State Trade Union'?", ["The Central or State Government, respectively", "The Industrial Tribunal", "The Supreme Court", "The International Labour Organization"], "The appropriate government may recognise a trade union or federation as a Central or State Trade Union for tripartite representation.");
b.q(2, "Which notice is an employer required to give before effecting a change in conditions of service such as wages or hours of work under the IR Code?", ["21 days' notice of change", "7 days' notice of change", "No notice is required", "90 days' notice of change"], "Section 40 requires notice of at least twenty-one days before effecting a change in matters listed in the Third Schedule.");
b.q(1, "A worker employed under fixed-term employment under the Labour Codes becomes eligible for gratuity after completing:", ["One year of service", "Five years of service", "Three years of service", "Six months of service"], "The Codes make fixed-term employees eligible for gratuity on a pro-rata basis after one year of continuous service (instead of five).");
b.q(3, "The IR Code empowers the appropriate government to increase the threshold of 300 workers for prior permission for lay-off, retrenchment and closure:", ["By notification", "Only by amending the Code in Parliament", "Only with the consent of the ILO", "Only with the consent of all trade unions"], "Section 77 allows the threshold to be raised by notification of the appropriate government.");
b.q(2, "Voluntary reference of an industrial dispute to arbitration under the IR Code requires:", ["A written agreement between employer and workers", "An order of the High Court", "Approval of the ILO", "A referendum among shareholders"], "Section 42: employer and workers may, by written agreement, refer an existing or apprehended dispute to an arbitrator before it is referred to a Tribunal.");
b.st(2, "Consider the following statements about standing orders under the IR Code:", ["The Central Government prepares model standing orders.", "If an establishment adopts the model standing orders, they are deemed certified.", "Standing orders apply to establishments with 50 or more workers."], [1, 2], "Model standing orders are framed by the Centre; adopted model orders are deemed certified. Applicability is 300 or more workers, not 50.");
b.q(2, "A worker who is placed under suspension pending inquiry is entitled under the IR Code to subsistence allowance of what share of wages for the first ninety days?", ["50%", "25%", "75%", "100%"], "Subsistence allowance is 50% of wages for the first 90 days and 75% thereafter if the delay is not attributable to the worker.");
b.q(3, "Under the IR Code, a disciplinary inquiry against a suspended worker should ordinarily be completed within:", ["Ninety days", "Thirty days", "Six months", "One year"], "The Code expects the inquiry to be completed ordinarily within ninety days.");
b.q(2, "A 'conciliation officer' under the IR Code primarily:", ["Mediates and promotes settlement of industrial disputes", "Awards compensation like a court", "Registers trade unions", "Certifies standing orders"], "Conciliation officers mediate between parties to bring about a fair settlement; they do not adjudicate.");
b.q(3, "Which of the following is NOT an 'unfair labour practice' on the part of an employer listed in the IR Code?", ["Taking disciplinary action against a worker after a fair domestic inquiry", "Interfering with workers' right to organise", "Establishing employer-sponsored trade unions", "Discharging a worker for filing charges under the Code"], "Disciplinary action after a fair inquiry is lawful; the others are listed unfair labour practices in the Second Schedule.");
b.q(1, "Under the IR Code, a settlement arrived at in the course of conciliation is binding on:", ["All parties to the dispute, including present and future workers of the establishment", "Only union members", "Only the employer", "No one unless approved by Parliament"], "A conciliation settlement binds all parties, all present and future workers of the establishment, and successors of the employer.");
b.q(2, "Under the IR Code, the National Industrial Tribunal is constituted by:", ["The Central Government", "The State Government", "The Supreme Court", "Employers' associations"], "The Centre constitutes National Industrial Tribunals for disputes of national importance or affecting establishments in more than one State.");
b.q(3, "Under the IR Code, the retrenchment of a worker with at least one year of continuous service (in an establishment below the Chapter X threshold) requires:", ["One month's notice or wages in lieu, and retrenchment compensation", "Only an oral intimation", "Six months' notice and approval of the High Court", "Consent of the worker's family"], "Conditions precedent: one month's written notice with reasons (or wages in lieu), retrenchment compensation, and notice to the government.");
b.ar(2, "The IR Code raised the threshold for applicability of standing orders from 100 to 300 workers.", "The Code aims to give establishments greater flexibility while model standing orders protect workers.", "a", "The higher threshold was part of the flexibility-cum-protection approach of the Code; model standing orders fill gaps.");
b.q(2, "Under the IR Code, 'last come, first go' is the principle followed in:", ["Retrenchment", "Promotion", "Overtime allocation", "Leave sanction"], "Retrenchment ordinarily follows seniority within the category — the worker employed last is retrenched first — unless reasons are recorded.");
b.q(3, "Under the IR Code, a retrenched worker must be given preference when the employer proposes to re-employ persons within:", ["One year of retrenchment", "Three months", "Five years", "Ten years"], "Section 72: retrenched workers get preference for re-employment if the employer recruits within one year.");

b.t("OSH Code");
b.q(1, "How many central laws were subsumed in the Occupational Safety, Health and Working Conditions Code, 2020?", ["13", "9", "4", "3"], "The OSH Code consolidates 13 laws including the Factories Act, Mines Act, Dock Workers Act, Plantations Labour Act and Contract Labour Act.");
b.q(2, "Under the OSH Code, a premises using power becomes a 'factory' when it employs at least:", ["20 workers", "10 workers", "40 workers", "50 workers"], "The threshold was raised from 10 to 20 workers with power and from 20 to 40 workers without power.");
b.q(2, "Under the OSH Code, a premises carrying on a manufacturing process WITHOUT the aid of power is a 'factory' if it employs at least:", ["40 workers", "20 workers", "10 workers", "100 workers"], "Without power, the factory threshold is 40 workers (earlier 20 under the Factories Act).");
b.q(2, "Under the OSH Code, the provisions relating to contract labour apply to establishments or contractors employing at least:", ["50 contract workers", "20 contract workers", "10 contract workers", "100 contract workers"], "The threshold was raised from 20 (under the Contract Labour Act, 1970) to 50 contract workers.");
b.q(1, "The OSH Code generally applies to establishments employing at least:", ["10 workers", "20 workers", "50 workers", "5 workers"], "The general applicability is 10 or more workers; mines and docks are covered regardless of the number employed.");
b.q(2, "Under the OSH Code, women may be employed before 6 a.m. and beyond 7 p.m.:", ["With their consent and subject to conditions on safety, holidays and working hours", "Never, as night work for women is banned", "Only in hospitals", "Only if accompanied by a family member"], "Section 43 permits women in all establishments for all work, including night shifts with consent and safety safeguards.");
b.q(2, "Under the OSH Code, a worker becomes eligible for annual leave with wages after working for how many days in a calendar year?", ["180 days", "240 days", "120 days", "300 days"], "The eligibility was reduced from 240 days (Factories Act) to 180 days.");
b.q(2, "Annual leave with wages under the OSH Code is earned at the rate of one day for every how many days of work performed by an adult worker?", ["20 days", "15 days", "30 days", "10 days"], "An adult worker earns one day's leave for every twenty days of work in the previous calendar year.");
b.q(1, "The OSH Code limits the daily working hours of a worker to not more than:", ["8 hours", "9 hours", "10 hours", "12 hours"], "Section 25: no worker shall be required or allowed to work for more than eight hours in a day (weekly limits are notified).");
b.q(2, "Which new right did the OSH Code give to every employee irrespective of the size of the establishment covered by it?", ["An appointment letter on joining", "A company car", "A share in profits", "Free housing"], "Every employer must issue an appointment letter to each employee on appointment.");
b.q(3, "The OSH Code provides for a free annual health check-up for employees of a specified age group. Under the central rules, this applies to employees aged:", ["40 years and above", "50 years and above", "18 years and above", "60 years and above"], "The Code provides annual free health examination for employees above a prescribed age (40 years under the draft central rules) in notified establishments.");
b.q(2, "Under the OSH Code, an inter-State migrant worker is entitled to an annual lump-sum amount for:", ["A to-and-fro journey to the native place", "Purchase of a house", "Children's school fees", "Medical insurance premium"], "Section 60 provides an annual journey allowance for travel to the worker's native place and back.");
b.st(2, "Consider the following statements about inter-State migrant workers under the OSH Code:", ["Workers who migrate on their own, not only through a contractor, are covered.", "A workers' database and toll-free helpline are envisaged.", "Migrant workers lose access to the Public Distribution System outside their home State."], [1, 2], "The OSH Code widens the definition to self-migrating workers and envisages a database and helpline; portability of benefits (including PDS) is intended, not denial.");
b.q(3, "The definition of inter-State migrant worker in the OSH Code covers a worker earning up to (or as notified):", ["₹18,000 per month", "₹10,000 per month", "₹25,000 per month", "No wage limit"], "An inter-State migrant worker is one who comes from another State and draws wages up to ₹18,000 per month (or as notified).");
b.q(2, "The OSH Code prohibits employment of contract labour in core activities of an establishment, except in certain situations. Which of the following is one such exception?", ["The normal functioning of the establishment is such that the activity is ordinarily done through contractors", "The contractor is a relative of the employer", "The contract workers earn more than permanent workers", "The establishment is a listed company"], "Exceptions include activities ordinarily done through contractors, activities not requiring full-time workers for most of the day, and sudden increases in volume of work.");
b.q(1, "Under the OSH Code, overtime work requires:", ["The consent of the worker and payment at twice the ordinary rate", "Only a verbal instruction from the supervisor", "Payment at the ordinary rate", "Permission of the High Court"], "Overtime is permitted only with the worker's consent and is paid at twice the ordinary rate of wages.");
b.q(2, "Which body advises the Central Government on matters dealt with in the OSH Code?", ["National Occupational Safety and Health Advisory Board", "Central Board of Trustees", "ESI Corporation", "National Green Tribunal"], "A tripartite National OSH Advisory Board replaces multiple boards under the earlier Acts.");
b.q(3, "The OSH Code subsumed the Working Journalists and Other Newspaper Employees Act, 1955. The OSH Code defines 'working journalist' to include:", ["Journalists working in electronic and digital media, besides newspapers", "Only print journalists", "Only government information officers", "Only editors"], "The Code broadens 'working journalist' to cover electronic and digital media.");
b.q(2, "Which of the following Acts was NOT subsumed in the OSH Code?", ["Industrial Disputes Act, 1947", "Beedi and Cigar Workers (Conditions of Employment) Act, 1966", "Sales Promotion Employees (Conditions of Service) Act, 1976", "Dock Workers (Safety, Health and Welfare) Act, 1986"], "The ID Act went into the IR Code; the others are among the 13 laws in the OSH Code.");
b.q(3, "Which of the following is among the laws consolidated in the OSH Code?", ["Cine-Workers and Cinema Theatre Workers (Regulation of Employment) Act, 1981", "Cine-Workers Welfare Fund Act, 1981", "Employees' Compensation Act, 1923", "Unorganised Workers' Social Security Act, 2008"], "The Cine-Workers and Cinema Theatre Workers (RoE) Act went into the OSH Code; the Cine-Workers Welfare Fund Act went into the Code on Social Security.");
b.q(2, "Under the OSH Code, a 'hazardous process' is one that, if not controlled, could:", ["Cause material impairment to the health of persons engaged or pollute the environment", "Reduce the profit of the company", "Delay production schedules", "Increase electricity bills"], "Hazardous process relates to processes listed in the schedule where raw materials, products or wastes could impair health or cause environmental pollution.");
b.q(1, "The Factories Act, 1948, now subsumed in the OSH Code, had a separate chapter on hazardous processes inserted in 1987. This followed which event?", ["The Bhopal gas tragedy of 1984", "The Chasnala mine disaster of 1975", "The Surat plague of 1994", "The Kutch earthquake of 2001"], "Chapter IV-A on hazardous processes was added by the Factories (Amendment) Act, 1987, after the Bhopal gas leak.");
b.q(3, "Under the OSH Code, the occupier of a factory carrying on a hazardous process must constitute which committee with equal worker and management representation?", ["A Safety Committee", "A Works Committee", "A Canteen Managing Committee", "An Audit Committee"], "Safety committees with equal representation of workers and management are required in factories carrying on hazardous processes and other notified establishments.");
b.q(2, "Which of the following is a 'welfare facility' required under the OSH Code (subject to thresholds)?", ["Canteen", "Gymnasium", "Swimming pool", "Cinema hall"], "Welfare facilities include canteens, creches, first-aid, washing, sitting arrangements, shelters and lunch rooms, subject to prescribed thresholds.");
b.q(3, "Under the OSH Code, a contractor engaging contract labour must obtain a licence. One feature of the Code is:", ["A single licence for undertaking work in more than one State or for the whole country", "Licence renewal every month", "No licence for any contractor", "Licence issued only by the ILO"], "The OSH Code provides for a single licence (for work in more than one State or across India), replacing work-order-wise licences.");
b.ar(3, "The OSH Code raised the threshold for applicability of contract labour provisions from 20 to 50 workers.", "The Code abolished the principal employer's responsibility for welfare facilities to contract workers.", "c", "A is correct. R is false: the principal employer remains responsible for welfare facilities (drinking water, toilets, first-aid) for contract labour.");
b.q(2, "Under the OSH Code, the person who has ultimate control over the affairs of a factory is called the:", ["Occupier", "Manager", "Inspector-cum-Facilitator", "Contractor"], "The occupier is the person with ultimate control over the affairs of the factory; in companies, a director is treated as occupier.");
b.q(2, "An audio-visual worker under the OSH Code is a person employed in:", ["Production of films, television programmes or digital content", "A sound-recording studio only as a cleaner", "A newspaper press", "A ration shop"], "The Code widens 'cine workers' to audio-visual workers, covering films, TV, web series and other digital production.");
b.q(1, "Under the OSH Code, which of the following establishments is covered irrespective of the number of workers employed?", ["Mines", "Retail shops", "Software firms", "Restaurants"], "Mines and docks are covered irrespective of the number of workers because of inherent risks.");
b.q(3, "Under the OSH Code, if a contravention of safety provisions causes the death of a worker, a court may direct that a portion of the fine be paid to:", ["The victim or the legal heirs", "The trade union", "The Inspector-cum-Facilitator", "The local police station"], "Courts may direct that not less than 50% of the fine be paid as compensation to the victim or legal heirs.");
b.q(2, "The Code that requires a 'national database' for inter-State migrant workers and unorganised workers along with Aadhaar-based registration is primarily:", ["The OSH Code read with the Code on Social Security", "The Code on Wages alone", "The IR Code alone", "The Companies Act"], "Database provisions appear in the OSH Code (migrant workers) and the Code on Social Security (unorganised workers via self-registration).");
b.q(2, "Which of the following is permitted for women workers under the OSH Code?", ["Work in mines, including below ground, subject to safeguards", "No employment in mines at all", "Only clerical work in factories", "Only day shifts in all establishments"], "The OSH Code allows women to work in all establishments, including underground mines during the day and in technical/supervisory roles at night, subject to safeguards.");
b.st(3, "Consider the following about safety officers and welfare officers under the OSH Code:", ["Thresholds for appointing safety officers are prescribed by the appropriate government.", "The Code removed all requirements to appoint welfare officers."], [1], "The OSH Code retains welfare officer requirements (thresholds as prescribed) and safety officer requirements notified by the appropriate government.");
b.q(1, "The OSH Code makes it the duty of every employer to ensure that the workplace is free from:", ["Hazards which cause or are likely to cause injury or occupational disease", "Trade union activity", "Women workers", "Overtime claims"], "Section 6 places a general duty on employers to keep workplaces free from hazards causing injury or occupational disease.");
b.q(3, "Under the OSH Code, a worker who has reasonable apprehension of imminent danger to life or health at the workplace may:", ["Bring it to the notice of the employer, who must take remedial action", "Be dismissed for raising it", "Only complain after an accident occurs", "Approach only the police"], "Workers' right to information and to report imminent danger is recognised; the employer must take remedial action if satisfied.");
b.q(2, "Under the OSH Code, the spread-over of working hours of a worker in a day (including rest intervals) ordinarily cannot exceed:", ["10.5 hours", "12 hours", "9 hours", "14 hours"], "Spread-over including intervals is limited (10.5 hours under the Factories Act; the Code empowers rules within similar limits).");
b.q(2, "The OSH Code applies to 'plantations' which, as defined, include those with at least:", ["5 hectares and 10 or more workers", "1 hectare and 2 workers", "100 hectares and 100 workers", "Any area employing family labour"], "Plantations of five hectares or more with ten or more workers are covered; States may extend coverage to smaller ones.");

export default b.items;
